def check_gross_margin_formulas(result: str, rule: Dict[str, Any]) -> float:
    """Verify Gross Margin (%) cells use row formulas, not hard-coded values."""
    try:
        if result is None or not os.path.exists(result):
            logger.error(f"Result file not found: {result}")
            return 0.0

        wb = openpyxl.load_workbook(filename=result, data_only=False)
        sheet_name = rule.get("sheet_name") or wb.sheetnames[rule.get("sheet_index", 0)]
        ws = wb[sheet_name]

        header_row = int(rule.get("header_row", 1))
        target_header = rule.get("target_header", "Gross Margin (%)")
        revenue_header = rule.get("revenue_header", "Revenue ($)")
        cogs_header = rule.get("cogs_header", "COGS ($)")
        data_start_row = int(rule.get("data_start_row", header_row + 1))

        headers = {}
        for cell in ws[header_row]:
            if cell.value is not None:
                headers[str(cell.value).strip()] = cell.column

        for required in (target_header, revenue_header, cogs_header):
            if required not in headers:
                logger.error(f"Required header not found: {required}")
                return 0.0

        target_col = headers[target_header]
        revenue_col = headers[revenue_header]
        cogs_col = headers[cogs_header]
        target_letter = get_column_letter(target_col)
        revenue_letter = get_column_letter(revenue_col)
        cogs_letter = get_column_letter(cogs_col)

        max_row = int(rule.get("data_end_row") or ws.max_row)
        for row in range(data_start_row, max_row + 1):
            revenue_value = ws.cell(row=row, column=revenue_col).value
            cogs_value = ws.cell(row=row, column=cogs_col).value
            if revenue_value is None and cogs_value is None:
                continue

            cell = ws.cell(row=row, column=target_col)
            formula = cell.value
            if not isinstance(formula, str) or not formula.startswith("="):
                logger.warning(f"{target_letter}{row} is not a formula: {formula!r}")
                return 0.0

            normalized = formula.upper().replace("$", "").replace(" ", "").replace(";", ",")
            expected_refs = (f"{revenue_letter}{row}", f"{cogs_letter}{row}")
            if any(ref not in normalized for ref in expected_refs):
                logger.warning(f"{target_letter}{row} does not reference row inputs: {formula!r}")
                return 0.0

            if rule.get("require_round", True) and "ROUND(" not in normalized:
                logger.warning(f"{target_letter}{row} does not use ROUND: {formula!r}")
                return 0.0

            if rule.get("require_two_decimals", True) and ",2" not in normalized:
                logger.warning(f"{target_letter}{row} does not round to 2 decimals: {formula!r}")
                return 0.0

            if rule.get("require_percent_100", True) and "100" not in normalized:
                logger.warning(f"{target_letter}{row} does not multiply by 100: {formula!r}")
                return 0.0

        return 1.0
    except Exception as e:
        logger.error(f"check_gross_margin_formulas error: {e}")
        return 0.0


def _parse_sheet_idx(
    sheet_idx: Union[int, str],
    result: BOOK,
    expected: BOOK,
    result_sheet_names: List[str],
    expected_sheet_names: List[str],
) -> Tuple[BOOK, str]:
    #  function _parse_sheet_idx {{{ #
    if isinstance(sheet_idx, int):
        try:
            if not result_sheet_names or sheet_idx >= len(result_sheet_names):
                logger.error(
                    f"Sheet index {sheet_idx} out of range. Available sheets: {result_sheet_names}"
                )
                index = ""
            else:
                index: str = result_sheet_names[sheet_idx]
                logger.debug(f"Sheet index {sheet_idx} resolved to sheet: {index}")
        except Exception as e:
            logger.error(f"Error resolving sheet index {sheet_idx}: {e}")
            index = ""
        book: BOOK = result
    elif sheet_idx.startswith("RI"):
        try:
            index: str = result_sheet_names[int(sheet_idx[2:])]
        except:
            index = ""
        book: BOOK = result
    elif sheet_idx.startswith("RN"):
        index: str = sheet_idx[2:]
        book: BOOK = result
    elif sheet_idx.startswith("EI"):
        try:
            index: str = expected_sheet_names[int(sheet_idx[2:])]
        except:
            index = ""
        book: BOOK = expected
    elif sheet_idx.startswith("EN"):
        index: str = sheet_idx[2:]
        book: BOOK = expected
    else:
        logger.error("Unrecognized sheet index")
        raise ValueError("Unrecognized sheet index")
    return book, index


